def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'
    if n == 99:
        return 'D'

    opp_C = 0
    opp_D = 0
    my_D = 0
    for a, b in history:
        if b == 'C':
            opp_C += 1
        else:
            opp_D += 1
        if a == 'D':
            my_D += 1

    if opp_C == 0:
        return 'D'

    if n >= 10:
        opp_D_rate = opp_D / n
        my_D_rate = my_D / n
        if opp_D_rate >= 0.3 and my_D_rate < 0.15:
            return 'D'

    opp_C_after_my_D = 0
    for i in range(1, n):
        if history[i-1][0] == 'D' and history[i][1] == 'C':
            opp_C_after_my_D += 1

    if my_D == 0:
        if n == 5:
            return 'D'
        return 'C'

    forgiveness = opp_C_after_my_D / my_D
    last_my, last_opp = history[-1]

    if forgiveness > 0.7:
        if last_my == 'C' and last_opp == 'C':
            return 'D'
        else:
            return 'C'

    if last_opp == 'D':
        return 'C'

    recent_my_D = 0
    for a, b in history[-3:]:
        if a == 'D':
            recent_my_D += 1
    if recent_my_D == 0:
        if rng.random() < 0.05:
            return 'D'
    return 'C'
